Here’s a **simple and clean C++ program** that performs addition of two complex numbers using **constructor overloading** and a **friend function** 👇  

```cpp
#include <iostream>
using namespace std;

class Complex {
    float real, imag;

public:
    // Default constructor
    Complex() {
        real = 0;
        imag = 0;
    }

    // Parameterized constructor
    Complex(float r, float i) {
        real = r;
        imag = i;
    }

    // Friend function to add two complex numbers
    friend Complex add(Complex c1, Complex c2);

    // Function to display result
    void display() {
        cout << real << " + " << imag << "i" << endl;
    }
};

// Friend function definition
Complex add(Complex c1, Complex c2) {
    Complex temp;
    temp.real = c1.real + c2.real;
    temp.imag = c1.imag + c2.imag;
    return temp;
}

int main() {
    Complex c1(2.5, 3.5);
    Complex c2(1.5, 2.5);

    Complex sum = add(c1, c2);

    cout << "Sum of complex numbers: ";
    sum.display();

    return 0;
}
```

**💡 Explanation:**
- **Constructor Overloading:**  
  `Complex()` is default, and `Complex(float, float)` is parameterized — that’s overloading.  
- **Friend Function:**  
  The `add()` function accesses private members of both objects directly.  
- **Output Example:**  
  ```
  Sum of complex numbers: 4 + 6i
  ```

